  'steps.trusses.compat.qWhyTruss': 'Kafes kirişte her düğümün iki yer değiştirmesi vardır: u_x ve u_z. Çubuklar mafsallı olduğundan dönmeler rol oynamaz.',
  'steps.trusses.compat.qWhyFrame': 'Her düğümün u_x ve u_z yer değiştirmeleri vardır; düğüme rijit bağlı bir çubuk ulaşıyorsa bunlara bir θ dönmesi eklenir.',
  'steps.trusses.compat.qCaption': 'Numaralanmış global koordinatlar.',
  'steps.trusses.compat.direction': 'Doğrultu',
  'steps.trusses.compat.qTable': 'Global koordinatlar: her birinin düğümü ve doğrultusu.',
  'steps.trusses.compat.dir.ux': 'yatay (u_x)',
  'steps.trusses.compat.dir.uz': 'düşey (u_z)',
